const wd="<private-path>";
const cmd = `node --input-type=module <<'NODE'
import { mkdtemp, mkdir, writeFile, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const execFileAsync=promisify(execFile);
const source=process.cwd();
const root=await mkdtemp(join(tmpdir(),'disputatio-audit-'));
const config=join(root,'fake.yaml');
await writeFile(config,'judge:\\n  adapter: codex\\n  bin: '+join(source,'test/fakes/codex')+'\\n');
async function fixture(name,status) {
  const dir=join(root,name);
  await mkdir(join(dir,'raw'),{recursive:true});
  await writeFile(join(dir,'debate.md'),'# Disputatio debate\\n\\n## Task\\n\\nAudit task\\n\\n## Proposal — A\\n\\nA says X\\n');
  await writeFile(join(dir,'respondeo.md'),status);
  return dir;
}
async function run(args,response) {
  const output=join(root,'fake-output');
  await writeFile(output,[
    JSON.stringify({type:'item.completed',item:{type:'agent_message',text:response}}),
    JSON.stringify({type:'turn.completed'})
  ].join('\\n')+'\\n');
  try {
    const r=await execFileAsync(process.execPath,[join(source,'src/index.ts'),...args,'--config',config],{cwd:root,env:{...process.env,FAKE_STDOUT_FILE:output}});
    return {exit:0,stdout:r.stdout.trim(),stderr:r.stderr.trim().split('\\n').slice(-3)};
  } catch(e) {
    return {exit:e.code,stdout:(e.stdout??'').trim(),stderr:(e.stderr??'').trim().split('\\n').slice(-3)};
  }
}
try {
  const failed=await fixture('failed','Respondeo turn failed: budget');
  console.log('finalize_failed_saved',JSON.stringify(await run(['--finalize','--debate',failed],'# Fake report')));
  const resolved=await fixture('resolved','STATUS: RESOLVED\\n\\nRuling.');
  console.log('continue_resolved_saved',JSON.stringify(await run(['--continue','answer','--debate',resolved],'STATUS: NEEDS_INPUT\\n\\nMore questions')));
  console.log('continued_file',JSON.stringify(await readFile(join(resolved,'respondeo-2.md'),'utf8')));
} finally { await rm(root,{recursive:true,force:true}); }
NODE`;
const r=await tools.exec_command({cmd,workdir:wd,yield_time_ms:30000,max_output_tokens:3000});text(r);

